// ======================================================
// OFFER PROCESSOR & TEST DATA FILTER
// ======================================================
// Purpose:
// 1. Extract useful flight-offer information from Duffel.
// 2. Remove synthetic/test airlines.
// 3. Distinguish marketing carrier from operating carrier.
// 4. Use the operating carrier as the primary airline
//    when Duffel provides it.
// 5. Preserve all important flight information.
// 6. Never invent missing information.
//
// IMPORTANT:
// This node does NOT make booking decisions.
// It only cleans and normalizes Duffel output.
// ======================================================

const response = $input.all().map(i => i.json)[0] || {};

// ------------------------------------------------------
// Get offers safely
// ------------------------------------------------------

const offers =
  Array.isArray(response?.data?.offers)
    ? response.data.offers
    : [];

// ------------------------------------------------------
// Process each offer
// ------------------------------------------------------

const processedOffers = [];

for (const offer of offers) {

  // ----------------------------------------------------
  // Basic offer information
  // ----------------------------------------------------

  const offerId =
    offer?.id || null;

  const offerOwnerName =
    offer?.owner?.name || null;

  const offerOwnerCode =
    offer?.owner?.iata_code || null;

  // ----------------------------------------------------
  // Get first slice
  // ----------------------------------------------------

  const firstSlice =
    Array.isArray(offer?.slices)
      ? offer.slices[0]
      : null;

  // ----------------------------------------------------
  // Get first segment
  // ----------------------------------------------------

  const firstSegment =
    Array.isArray(firstSlice?.segments)
      ? firstSlice.segments[0]
      : null;

  // ----------------------------------------------------
  // Marketing carrier
  // ----------------------------------------------------

  const marketingCarrierName =
    firstSegment?.marketing_carrier?.name ||
    offerOwnerName ||
    null;

  const marketingCarrierCode =
    firstSegment?.marketing_carrier?.iata_code ||
    offerOwnerCode ||
    null;

  // ----------------------------------------------------
  // Operating carrier
  //
  // Duffel may provide this separately from the
  // marketing carrier.
  // ----------------------------------------------------

  const operatingCarrierName =
    firstSegment?.operating_carrier?.name ||
    null;

  const operatingCarrierCode =
    firstSegment?.operating_carrier?.iata_code ||
    null;

  // ----------------------------------------------------
  // Determine the primary airline
  //
  // Prefer the actual operating carrier when available.
  // Otherwise fall back to the marketing/owner carrier.
  // ----------------------------------------------------

  const primaryAirline =
    operatingCarrierName ||
    marketingCarrierName ||
    null;

  const primaryAirlineCode =
    operatingCarrierCode ||
    marketingCarrierCode ||
    null;

  // ----------------------------------------------------
  // Synthetic/test airline filtering
  //
  // We check both the offer owner and the operating /
  // marketing carriers so synthetic data is not allowed
  // through accidentally.
  // ----------------------------------------------------

  const carrierNames = [
    offerOwnerName,
    marketingCarrierName,
    operatingCarrierName
  ]
    .filter(Boolean)
    .map(name =>
      String(name).trim().toLowerCase()
    );

  const carrierCodes = [
    offerOwnerCode,
    marketingCarrierCode,
    operatingCarrierCode
  ]
    .filter(Boolean)
    .map(code =>
      String(code).trim().toUpperCase()
    );

  const isSyntheticOffer =
    carrierCodes.includes("ZZ") ||
    carrierNames.includes("duffel airways");

  if (isSyntheticOffer) {
    continue;
  }

  // ----------------------------------------------------
  // Origin and destination
  // ----------------------------------------------------

  const origin =
    firstSlice?.origin?.iata_code ||
    firstSegment?.origin?.iata_code ||
    null;

  const destination =
    firstSlice?.destination?.iata_code ||
    firstSegment?.destination?.iata_code ||
    null;

  // ----------------------------------------------------
  // Flight timing
  // ----------------------------------------------------

  const departure =
    firstSegment?.departing_at ||
    null;

  const arrival =
    firstSegment?.arriving_at ||
    null;

  // ----------------------------------------------------
  // Stops
  // ----------------------------------------------------

  const segments =
    Array.isArray(firstSlice?.segments)
      ? firstSlice.segments
      : [];

  const stops =
    segments.length > 0
      ? Math.max(segments.length - 1, 0)
      : null;

  // ----------------------------------------------------
  // Build normalized offer
  // ----------------------------------------------------

  processedOffers.push({
    json: {

      // ----------------------------------------------
      // Basic offer identity
      // ----------------------------------------------

      offer_id:
        offerId,

      // ----------------------------------------------
      // Primary airline used by downstream analysis
      // ----------------------------------------------

      airline:
        primaryAirline,

      airline_code:
        primaryAirlineCode,

      // ----------------------------------------------
      // Carrier distinction
      // ----------------------------------------------

      marketing_airline:
        marketingCarrierName,

      marketing_airline_code:
        marketingCarrierCode,

      operating_airline:
        operatingCarrierName,

      operating_airline_code:
        operatingCarrierCode,

      // ----------------------------------------------
      // Route
      // ----------------------------------------------

      origin:
        origin,

      destination:
        destination,

      // ----------------------------------------------
      // Fare
      // ----------------------------------------------

      price:
        offer?.total_amount != null
          ? Number(offer.total_amount)
          : null,

      currency:
        offer?.total_currency ||
        null,

      // ----------------------------------------------
      // Timing
      // ----------------------------------------------

      departure:
        departure,

      arrival:
        arrival,

      // ----------------------------------------------
      // Stops and duration
      // ----------------------------------------------

      stops:
        stops,

      duration:
        firstSlice?.duration ||
        null,

      // ----------------------------------------------
      // Cabin
      // ----------------------------------------------

      cabin:
        firstSegment?.passengers?.[0]?.cabin_class ||
        null,

      // ----------------------------------------------
      // Flight numbers
      // ----------------------------------------------

      marketing_flight_number:
        firstSegment?.marketing_carrier_flight_number ||
        null,

      operating_flight_number:
        firstSegment?.operating_carrier_flight_number ||
        null
    }
  });
}

// ------------------------------------------------------
// Return cleaned offers
// ------------------------------------------------------

return processedOffers;

const offers = $input.all().map(item => item.json);

const preferences = $('Preference Agent').first().json.output;

return [
  {
    json: {
      preferences,
      offers
    }
  }
];

// ======================================================
// FARE STATISTICS & BUDGET ANALYSIS
// ======================================================
// Purpose:
// 1. Preserve the Fare Intelligence output.
// 2. Calculate fare statistics.
// 3. Analyze budget compatibility.
// 4. Preserve preferred-airline information.
// 5. Preserve the cheapest suitable offer for downstream ML.
//
// IMPORTANT:
// - No ML prediction happens here.
// - No currency conversion happens here.
// - Different currencies are NOT numerically compared.
// ======================================================

// ------------------------------------------------------
// 1. Read Fare Intelligence output
// ------------------------------------------------------

const intelligence =
  $input.first().json.output || $input.first().json;

// Support the actual output structure from the
// Fare Intelligence Agent.
const fareData =
  intelligence.fare_intelligence || intelligence;

// ------------------------------------------------------
// 2. Read user preferences
// ------------------------------------------------------

const preferences =
  $('Preference Agent').first().json.output || {};

// ------------------------------------------------------
// 3. Extract important offers
// ------------------------------------------------------

const cheapestOffer =
  fareData.cheapest_overall_offer ||
  fareData.cheapest_offer ||
  null;

const cheapestSuitableOffer =
  fareData.cheapest_suitable_offer || null;

// ------------------------------------------------------
// 4. Extract cheapest fare information
// ------------------------------------------------------

const cheapestFare =
  cheapestOffer?.price != null
    ? Number(cheapestOffer.price)
    : null;

const fareCurrency =
  cheapestOffer?.currency || null;

// ------------------------------------------------------
// 5. Extract user budget
// ------------------------------------------------------

const userBudget =
  preferences.budget != null
    ? Number(preferences.budget)
    : null;

const budgetCurrency =
  preferences.currency || null;

// ------------------------------------------------------
// 6. Check whether currencies match
// ------------------------------------------------------

const currencyMatch =
  Boolean(budgetCurrency) &&
  Boolean(fareCurrency) &&
  budgetCurrency.toUpperCase() ===
    fareCurrency.toUpperCase();

// ------------------------------------------------------
// 7. Initialize budget analysis
// ------------------------------------------------------

let budgetStatus = "UNKNOWN";
let withinBudget = null;
let budgetDifference = null;

const currencyConversionRequired = !currencyMatch;

// ------------------------------------------------------
// 8. Compare budget only when currencies match
// ------------------------------------------------------

if (
  currencyMatch &&
  cheapestFare !== null &&
  Number.isFinite(cheapestFare) &&
  userBudget !== null &&
  Number.isFinite(userBudget)
) {
  budgetDifference = userBudget - cheapestFare;
  withinBudget = cheapestFare <= userBudget;

  budgetStatus = withinBudget
    ? "WITHIN_BUDGET"
    : "OVER_BUDGET";
} else if (!currencyMatch && cheapestFare !== null) {
  budgetStatus = "CURRENCY_CONVERSION_REQUIRED";
}

// ------------------------------------------------------
// 9. Extract relevant alternatives
// ------------------------------------------------------

const alternatives =
  fareData.alternative_offers ||
  fareData.relevant_alternatives ||
  fareData.suitable_alternatives ||
  [];

// ------------------------------------------------------
// 10. Collect prices for statistics
// ------------------------------------------------------
// Include only valid prices in the same currency.
// This avoids mixing GBP and INR in fare statistics.
// ------------------------------------------------------

const availablePrices = [];

if (
  cheapestFare !== null &&
  Number.isFinite(cheapestFare)
) {
  availablePrices.push(cheapestFare);
}

for (const alternative of alternatives) {
  const price =
    alternative.price != null
      ? Number(alternative.price)
      : NaN;

  const alternativeCurrency =
    alternative.currency || fareCurrency;

  if (
    Number.isFinite(price) &&
    (
      !fareCurrency ||
      alternativeCurrency.toUpperCase() ===
        fareCurrency.toUpperCase()
    )
  ) {
    availablePrices.push(price);
  }
}

// ------------------------------------------------------
// 11. Calculate fare statistics
// ------------------------------------------------------

const lowestFare =
  availablePrices.length > 0
    ? Math.min(...availablePrices)
    : null;

const highestFare =
  availablePrices.length > 0
    ? Math.max(...availablePrices)
    : null;

const averageFare =
  availablePrices.length > 0
    ? availablePrices.reduce(
        (sum, price) => sum + price,
        0
      ) / availablePrices.length
    : null;

// ------------------------------------------------------
// 12. Preserve preferred-airline information
// ------------------------------------------------------

const preferredAirline = {
  requested:
    preferences.airline_preference || null,

  available:
    fareData.preferred_airline_availability ??
    fareData.preferred_airline_available ??
    false,

  cheapest_offer:
    fareData.preferred_airline_offer ??
    fareData.preferred_airline_cheapest_offer ??
    null
};

// ------------------------------------------------------
// 13. FINAL OUTPUT
// ------------------------------------------------------

return [
  {
    json: {
      // USER PREFERENCES
      preferences: {
        origin: preferences.origin || null,
        destination: preferences.destination || null,
        departure_date: preferences.departure_date || null,
        return_date: preferences.return_date || null,
        passengers: preferences.passengers ?? null,
        budget: userBudget,
        currency: budgetCurrency,
        airline_preference:
          preferences.airline_preference || null,
        cabin_preference:
          preferences.cabin_preference || null,
        flexibility: preferences.flexibility || null
      },

      // FARE STATISTICS
      fare_statistics: {
        offers_analyzed: availablePrices.length,
        lowest_fare: lowestFare,
        highest_fare: highestFare,
        average_fare: averageFare,
        fare_currency: fareCurrency
      },

      // BUDGET ANALYSIS
      budget_analysis: {
        user_budget: userBudget,
        budget_currency: budgetCurrency,
        cheapest_fare: cheapestFare,
        fare_currency: fareCurrency,
        currency_match: currencyMatch,
        currency_conversion_required:
          currencyConversionRequired,
        budget_status: budgetStatus,
        within_budget: withinBudget,
        budget_difference: budgetDifference
      },

      // PREFERRED AIRLINE
      preferred_airline: preferredAirline,

      // CHEAPEST CURRENT OFFER
      cheapest_offer: cheapestOffer,

      // CHEAPEST SUITABLE OFFER
      cheapest_suitable_offer: cheapestSuitableOffer,

      // ALTERNATIVES
      alternatives: alternatives,

      // FARE OBSERVATIONS
      fare_observations:
        fareData.fare_observations || [],

      // SUMMARY
      analysis_summary:
        fareData.analysis_summary || ""
    }
  }
];

/**
 * ML INPUT PREPARATION
 *
 * - Preserves the existing fare-analysis output.
 * - Reads every cleaned offer from Offer Processor & Test Data Filter.
 * - Prefers a compatible offer matching the user's airline preference.
 * - Otherwise selects a compatible comparison offer.
 * - Never invents missing route or airline information.
 * - Allows future-year attempts; the API must label extrapolations.
 */

const input = $input.first().json;

const preferences =
  $('Preference Agent').first().json.output || {};

const processedOffers =
  $('Offer Processor & Test Data Filter')
    .all()
    .map(item => item.json);

// --------------------------------------------------
// Supported routes
// --------------------------------------------------

const routeDefinitions = [
  { route: "Delhi Ã¢â€ â€ Mumbai", forward: ["DEL", "BOM"], backward: ["BOM", "DEL"] },
  { route: "Delhi Ã¢â€ â€ Bangalore", forward: ["DEL", "BLR"], backward: ["BLR", "DEL"] },
  { route: "Delhi Ã¢â€ â€ Hyderabad", forward: ["DEL", "HYD"], backward: ["HYD", "DEL"] },
  { route: "Mumbai Ã¢â€ â€ Bangalore", forward: ["BOM", "BLR"], backward: ["BLR", "BOM"] },
  { route: "Mumbai Ã¢â€ â€ Hyderabad", forward: ["BOM", "HYD"], backward: ["HYD", "BOM"] },
  { route: "Bangalore Ã¢â€ â€ Hyderabad", forward: ["BLR", "HYD"], backward: ["HYD", "BLR"] }
];

const airportToCity = {
  DEL: "Delhi",
  BOM: "Mumbai",
  BLR: "Bangalore",
  HYD: "Hyderabad"
};

// --------------------------------------------------
// Airline normalization
// --------------------------------------------------

function normalizeAirline(value) {
  const name = String(value || "").trim().toLowerCase();

  const aliases = {
    "indigo": "IndiGo",
    "6e": "IndiGo",
    "vistara": "Vistara",
    "uk": "Vistara",
    "air india": "Air India",
    "ai": "Air India",
    "spicejet": "SpiceJet",
    "sg": "SpiceJet",
    "airasia": "AirAsia",
    "airasia india": "AirAsia"
  };

  return aliases[name] || null;
}

function getRoute(origin, destination) {
  for (const definition of routeDefinitions) {
    if (
      origin === definition.forward[0] &&
      destination === definition.forward[1]
    ) {
      return { route: definition.route, direction: "Ã¢â€ â€™" };
    }

    if (
      origin === definition.backward[0] &&
      destination === definition.backward[1]
    ) {
      return { route: definition.route, direction: "Ã¢â€ Â" };
    }
  }

  return { route: null, direction: null };
}

function getYear(offer) {
  const value =
    offer?.departure ||
    preferences?.departure_date ||
    null;

  if (!value) return null;

  const match = String(value).match(/^(\d{4})-/);

  if (match) return Number(match[1]);

  const date = new Date(value);

  return Number.isNaN(date.getTime())
    ? null
    : date.getUTCFullYear();
}

function prepareCandidate(offer) {
  if (!offer) return null;

  const origin = String(
    offer.origin || preferences?.origin || ""
  ).trim().toUpperCase();

  const destination = String(
    offer.destination || preferences?.destination || ""
  ).trim().toUpperCase();

  const rawAirline = String(offer.airline || "").trim();
  const airline = normalizeAirline(rawAirline);
  const routeInfo = getRoute(origin, destination);
  const year = getYear(offer);

  // Do not use an offer for a different journey
  // when the requested airports are available.
  const requestedOrigin =
    String(preferences?.origin || "").trim().toUpperCase();

  const requestedDestination =
    String(preferences?.destination || "").trim().toUpperCase();

  const matchesRequestedRoute =
    (!requestedOrigin || origin === requestedOrigin) &&
    (!requestedDestination || destination === requestedDestination);

  let reason = null;

  if (!matchesRequestedRoute) {
    reason = "Offer does not match the requested route.";
  } else if (!routeInfo.route) {
    reason = `ML training data does not cover route ${origin} Ã¢â€ â€™ ${destination}.`;
  } else if (!airline) {
    reason = `ML training data does not cover airline "${rawAirline || "unknown"}".`;
  } else if (year === null) {
    reason = "Departure year could not be determined.";
  } else if (!routeInfo.direction) {
    reason = "A valid travel direction could not be determined.";
  }

  return {
    offer,
    origin,
    destination,
    rawAirline,
    normalizedAirline: airline,
    year,
    route: routeInfo.route,
    direction: routeInfo.direction,
    available: reason === null,
    reason
  };
}

// --------------------------------------------------
// Gather candidate offers
// --------------------------------------------------

const preferredAirline = normalizeAirline(
  preferences?.airline_preference ||
  preferences?.preferred_airline ||
  ""
);

const preferredOffer =
  input.preferred_airline?.available === true
    ? input.preferred_airline?.cheapest_offer
    : null;

// Include the Fare Intelligence preferred offer, if any,
// plus every cleaned offer. Deduplicate by offer ID.
const rawCandidates = [];
const seenIds = new Set();

for (const offer of [preferredOffer, ...processedOffers]) {
  if (!offer) continue;

  const id = offer.offer_id || offer.id;

  if (id && seenIds.has(id)) continue;
  if (id) seenIds.add(id);

  rawCandidates.push(offer);
}

const candidates = rawCandidates
  .map(prepareCandidate)
  .filter(Boolean);

const compatibleCandidates =
  candidates.filter(candidate => candidate.available);

// --------------------------------------------------
// Choose the cheapest candidate safely
// --------------------------------------------------

// Prices in different currencies must not be compared
// as if they were the same currency.
function chooseCheapest(offers) {
  if (offers.length <= 1) return offers[0] || null;

  const currencies = new Set(
    offers.map(item =>
      String(item.offer.currency || "").toUpperCase()
    )
  );

  if (currencies.size !== 1 || currencies.has("")) {
    return offers[0];
  }

  return [...offers].sort((a, b) => {
    const priceA = Number(a.offer.price);
    const priceB = Number(b.offer.price);

    if (!Number.isFinite(priceA)) return 1;
    if (!Number.isFinite(priceB)) return -1;

    return priceA - priceB;
  })[0];
}

// First preference: a compatible offer from the requested airline.
let selected = null;
let selectionStatus = null;

const preferredCandidates = compatibleCandidates.filter(
  candidate =>
    preferredAirline &&
    candidate.normalizedAirline === preferredAirline
);

const compatiblePreferredOffer =
  preferredOffer
    ? prepareCandidate(preferredOffer)
    : null;

if (
  compatiblePreferredOffer?.available &&
  (
    !preferredAirline ||
    compatiblePreferredOffer.normalizedAirline === preferredAirline
  )
) {
  selected = compatiblePreferredOffer;
  selectionStatus = "PREFERRED_AIRLINE_OFFER_SELECTED";
} else if (preferredCandidates.length > 0) {
  selected = chooseCheapest(preferredCandidates);
  selectionStatus = "PREFERRED_AIRLINE_OFFER_SELECTED";
} else if (compatibleCandidates.length > 0) {
  selected = chooseCheapest(compatibleCandidates);
  selectionStatus = "ML_COMPATIBLE_COMPARISON_OFFER";
}

/*
 * FALLBACK: ML reference estimate for the requested journey.
 * Use this only when Duffel returned no ML-compatible offer.
 * This does NOT create or claim a bookable flight offer.
 */

if (!selected && preferredAirline) {
  const requestedOrigin =
    String(preferences?.origin || "").trim().toUpperCase();

  const requestedDestination =
    String(preferences?.destination || "").trim().toUpperCase();

  const routeInfo = getRoute(
    requestedOrigin,
    requestedDestination
  );

  const requestedYear = getYear({
    departure: preferences?.departure_date
  });

  const supportedAirlines = new Set([
    "IndiGo",
    "Vistara",
    "Air India",
    "SpiceJet",
    "AirAsia"
  ]);

  if (
    routeInfo.route &&
    routeInfo.direction &&
    supportedAirlines.has(preferredAirline) &&
    requestedYear !== null
  ) {
    selected = {
      offer: null,
      origin: requestedOrigin,
      destination: requestedDestination,
      rawAirline: preferredAirline,
      normalizedAirline: preferredAirline,
      year: requestedYear,
      route: routeInfo.route,
      direction: routeInfo.direction,
      available: true,
      reason: null
    };

    selectionStatus =
      "REQUESTED_JOURNEY_ML_REFERENCE_ESTIMATE";
  }
}

// --------------------------------------------------
// Explain why the ML candidate is unavailable
// --------------------------------------------------

let reason = null;

if (!selected) {
  if (candidates.length === 0) {
    reason = "No flight offers were available for ML evaluation.";
  } else {
    const requestedOrigin =
      String(preferences?.origin || "").trim().toUpperCase();

    const requestedDestination =
      String(preferences?.destination || "").trim().toUpperCase();

    const routeInfo = getRoute(
      requestedOrigin,
      requestedDestination
    );

    if (!routeInfo.route) {
      reason =
        `ML training data does not cover route ${requestedOrigin} Ã¢â€ â€™ ${requestedDestination}.`;
    } else if (
      !candidates.some(candidate => candidate.normalizedAirline)
    ) {
      reason =
        "None of the returned offers use an airline supported by the ML model.";
    } else {
      reason =
        "No returned offer satisfies all ML eligibility requirements for the requested journey.";
    }
  }
}

// --------------------------------------------------
// Build source-offer details
// --------------------------------------------------

function sourceOfferDetails(offer) {
  if (!offer) return null;

  return {
    offer_id: offer.offer_id || offer.id || null,
    airline: offer.airline || null,
    airline_code: offer.airline_code || null,
    origin: offer.origin || null,
    destination: offer.destination || null,
    price: offer.price ?? null,
    currency: offer.currency || null,
    departure: offer.departure || null,
    arrival: offer.arrival || null,
    stops: offer.stops ?? null,
    cabin: offer.cabin || null,
    duration: offer.duration || null
  };
}

// --------------------------------------------------
// Return original analysis plus ML information
// --------------------------------------------------

return [
  {
    json: {
      ...input,

      ml_input: {
        available: Boolean(selected),
        selection_status:
          selectionStatus || "NO_ML_COMPATIBLE_OFFER",
        reason,

        Route: selected?.route || null,
        Airline: selected?.normalizedAirline || null,
        Year: selected?.year ?? null,
        Direction: selected?.direction || null,

        source_offer:
          sourceOfferDetails(selected?.offer || null),

        comparison_offer:
          selectionStatus === "ML_COMPATIBLE_COMPARISON_OFFER"
            ? sourceOfferDetails(selected.offer)
            : null,

        requested_airline:
          preferredAirline || null,

        training_years: [2022, 2023],

        prediction_note:
          selected?.year > 2023
            ? "Future-year prediction is an extrapolation, not a validated future fare forecast or a live ticket price."
            : "ML output is a model-generated reference estimate, not a live ticket price."
      }
    }
  }
];

// ======================================================
// ML RESULT HANDLER - AVAILABLE
// ======================================================
// Purpose:
// Preserve the complete workflow data and attach the
// successful historical ML prediction.
//
// This node runs only when ML Coverage Router = TRUE.
// ======================================================

const originalData =
  $('ML Input Preparation').first().json;

const prediction =
  $input.first().json;

return [
  {
    json: {
      ...originalData,

      ml_result: {
        available: true,

        prediction_available:
          true,

        predicted_fare:
          prediction?.predicted_fare ?? null,

        currency:
          prediction?.currency || null,

        prediction_type:
          prediction?.prediction_type || null,

        reason:
          null,

        coverage: {
          covered:
            true,

          route:
            originalData?.ml_input?.Route || null,

          airline:
            originalData?.ml_input?.Airline || null,

          matching_training_records:
            null
        }
      }
    }
  }
];

// ======================================================
// ML NOT AVAILABLE
// ======================================================
// Purpose:
// Preserve the complete fare-intelligence data when the
// historical ML model does not cover the selected
// route + airline combination.
//
// The workflow must NOT stop simply because ML coverage
// is unavailable.
// ======================================================

const originalData =
  $('ML Input Preparation').first().json;

const coverageResult =
  $input.first().json;

return [
  {
    json: {
      ...originalData,

      ml_result: {
        available: false,

        prediction_available:
          false,

        predicted_fare:
          null,

        currency:
          null,

        prediction_type:
          null,

        reason:
          "Historical ML model does not cover the selected route and airline.",

        coverage: {
          covered:
            coverageResult?.covered ?? false,

          route:
            coverageResult?.route || null,

          airline:
            coverageResult?.airline || null,

          matching_training_records:
            coverageResult?.matching_training_records ?? 0
        }
      }
    }
  }
];

