const responses = $input.all();
const monitors = $('Load Monitoring State').all();

const results = [];

for (let i = 0; i < responses.length; i++) {
  const response = responses[i].json || {};
  const monitor = monitors[i]?.json || {};

  const offers = Array.isArray(response?.data?.offers)
    ? response.data.offers
    : [];

  const processedOffers = [];

  for (const offer of offers) {
    const ownerName = offer?.owner?.name || null;
    const ownerCode = offer?.owner?.iata_code || null;

    const firstSlice = Array.isArray(offer?.slices)
      ? offer.slices[0]
      : null;

    const segments = Array.isArray(firstSlice?.segments)
      ? firstSlice.segments
      : [];

    const firstSegment = segments[0] || null;

    const marketingName =
      firstSegment?.marketing_carrier?.name ||
      ownerName;

    const marketingCode =
      firstSegment?.marketing_carrier?.iata_code ||
      ownerCode;

    const operatingName =
      firstSegment?.operating_carrier?.name || null;

    const operatingCode =
      firstSegment?.operating_carrier?.iata_code || null;

    const carrierNames = [
      ownerName,
      marketingName,
      operatingName
    ]
      .filter(Boolean)
      .map(name => String(name).trim().toLowerCase());

    const carrierCodes = [
      ownerCode,
      marketingCode,
      operatingCode
    ]
      .filter(Boolean)
      .map(code => String(code).trim().toUpperCase());

    if (
      carrierCodes.includes("ZZ") ||
      carrierNames.includes("duffel airways")
    ) {
      continue;
    }

    processedOffers.push({
      offer_id: offer?.id || null,

      airline:
        operatingName || marketingName || null,

      airline_code:
        operatingCode || marketingCode || null,

      marketing_airline: marketingName || null,
      marketing_airline_code: marketingCode || null,

      operating_airline: operatingName,
      operating_airline_code: operatingCode,

      origin:
        firstSlice?.origin?.iata_code ||
        firstSegment?.origin?.iata_code ||
        null,

      destination:
        firstSlice?.destination?.iata_code ||
        firstSegment?.destination?.iata_code ||
        null,

      price: offer?.total_amount != null
        ? Number(offer.total_amount)
        : null,

      currency: offer?.total_currency || null,

      departure: firstSegment?.departing_at || null,
      arrival: firstSegment?.arriving_at || null,

      stops: segments.length > 0
        ? Math.max(segments.length - 1, 0)
        : null,

      duration: firstSlice?.duration || null,

      cabin:
        firstSegment?.passengers?.[0]?.cabin_class ||
        null,

      marketing_flight_number:
        firstSegment?.marketing_carrier_flight_number ||
        null,

      operating_flight_number:
        firstSegment?.operating_carrier_flight_number ||
        null
    });
  }

  results.push({
    json: {
      monitor: {
        monitor_id: monitor.monitor_id || null,
        origin: monitor.origin || null,
        destination: monitor.destination || null,
        departure_date: monitor.departure_date || null,
        passengers: monitor.passengers ?? null,
        budget: monitor.budget ?? null,
        currency: monitor.currency || null,
        preferred_airline: monitor.preferred_airline || null,
        last_fare: monitor.last_fare ?? null,
        last_currency: monitor.last_currency || null,
        last_decision: monitor.last_decision || null,
        last_checked: monitor.last_checked || null
      },

      offers: processedOffers,
      offer_count: processedOffers.length
    }
  });
}

return results;

const inputs = $input.all();
const results = [];

for (const item of inputs) {
  const input = item.json || {};
  const monitor = input.monitor || {};
  const offers = Array.isArray(input.offers) ? input.offers : [];

  const previousFare =
    monitor.last_fare != null ? Number(monitor.last_fare) : null;

  const previousCurrency =
    String(monitor.last_currency || monitor.currency || "INR").toUpperCase();

  const budget =
    monitor.budget != null ? Number(monitor.budget) : null;

  const budgetCurrency =
    String(monitor.currency || "INR").toUpperCase();

  const preferredAirline =
    String(monitor.preferred_airline || "").trim().toUpperCase();

  const matchingOffers = offers.filter(offer => {
    const originMatches =
      String(offer.origin || "").toUpperCase() ===
      String(monitor.origin || "").toUpperCase();

    const destinationMatches =
      String(offer.destination || "").toUpperCase() ===
      String(monitor.destination || "").toUpperCase();

    const airlineMatches =
      !preferredAirline ||
      String(offer.airline_code || "").toUpperCase() === preferredAirline ||
      String(offer.airline || "").trim().toUpperCase() === preferredAirline;

    const priceIsValid =
      Number.isFinite(Number(offer.price)) &&
      offer.price !== null &&
      Boolean(offer.currency);

    return originMatches && destinationMatches &&
      airlineMatches && priceIsValid;
  });

  const currencyMatches = matchingOffers.filter(offer =>
    String(offer.currency).toUpperCase() === budgetCurrency
  );

  currencyMatches.sort((a, b) => Number(a.price) - Number(b.price));

  const cheapest = currencyMatches[0] || null;

  let fareChange = null;
  let fareDropPercent = null;

  if (
    cheapest &&
    previousFare !== null &&
    Number.isFinite(previousFare) &&
    previousCurrency === String(cheapest.currency).toUpperCase()
  ) {
    fareChange = Number(cheapest.price) - previousFare;
    fareDropPercent = previousFare > 0
      ? ((previousFare - Number(cheapest.price)) / previousFare) * 100
      : null;
  }

  const belowBudget =
    cheapest !== null &&
    budget !== null &&
    Number.isFinite(budget) &&
    String(cheapest.currency).toUpperCase() === budgetCurrency &&
    Number(cheapest.price) <= budget;

  results.push({
    json: {
      monitor,
      monitoring_analysis: {
        current_offer_count: matchingOffers.length,
        currency_matched_offer_count: currencyMatches.length,
        cheapest_current_offer: cheapest,
        previous_fare: previousFare,
        previous_currency: previousCurrency,
        budget,
        budget_currency: budgetCurrency,
        fare_change: fareChange,
        fare_drop_percent: fareDropPercent,
        below_budget: belowBudget,
        currency_comparable:
          Boolean(cheapest) &&
          String(cheapest.currency).toUpperCase() === previousCurrency,
        analysis_status: cheapest
          ? "OFFERS_FOUND"
          : "NO_COMPARABLE_OFFERS"
      }
    }
  });
}

return results;

const exchangeItems = $input.all();
const analysisItems = $('Monitoring Analysis').all();
const processorItems = $('Monitoring Offer Processor').all();

const results = [];

function toNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

for (let i = 0; i < processorItems.length; i++) {
  const processed = processorItems[i]?.json || {};
  const analysis = analysisItems[i]?.json || {};
  const exchangeData = exchangeItems[i]?.json || {};

  const monitor = processed.monitor || analysis.monitor || {};
  const monitoring = analysis.monitoring_analysis || {};
  const offers = Array.isArray(processed.offers)
    ? processed.offers
    : [];

  const targetCurrency = String(monitor.currency || 'INR').toUpperCase();
  const budget = toNumber(monitor.budget);
  const previousFare = toNumber(monitor.last_fare);
  const previousCurrency = String(
    monitor.last_currency || targetCurrency
  ).toUpperCase();

  const rates = exchangeData.rates || {};
  const baseCode = String(
    exchangeData.base_code || ''
  ).toUpperCase();

  function convertToTarget(amount, sourceCurrency) {
    const price = toNumber(amount);
    const source = String(sourceCurrency || '').toUpperCase();

    if (price === null || !source || !targetCurrency) {
      return null;
    }

    if (source === targetCurrency) {
      return price;
    }

    // This workflow requests rates with INR as the base.
    // rates.GBP means how many GBP equal 1 INR.
    if (baseCode === 'INR' && targetCurrency === 'INR') {
      const sourceRate = toNumber(rates[source]);

      if (sourceRate === null || sourceRate <= 0) {
        return null;
      }

      return price / sourceRate;
    }

    // General conversion when the API base matches the source currency.
    if (baseCode === source) {
      const targetRate = toNumber(rates[targetCurrency]);

      if (targetRate === null) {
        return null;
      }

      return price * targetRate;
    }

    return null;
  }

  const normalizedOffers = offers
    .filter(offer =>
      String(offer.origin || '').toUpperCase() ===
        String(monitor.origin || '').toUpperCase() &&
      String(offer.destination || '').toUpperCase() ===
        String(monitor.destination || '').toUpperCase()
    )
    .map(offer => {
      const originalPrice = toNumber(offer.price);
      const originalCurrency = String(
        offer.currency || ''
      ).toUpperCase();

      const converted = convertToTarget(
        originalPrice,
        originalCurrency
      );

      const normalizedPrice = converted === null
        ? null
        : Number(converted.toFixed(2));

      return {
        ...offer,
        original_price: originalPrice,
        original_currency: originalCurrency || null,
        normalized_price: normalizedPrice,
        normalized_currency: targetCurrency,
        exchange_rate: normalizedPrice !== null &&
          originalPrice !== null &&
          originalPrice !== 0
            ? Number((normalizedPrice / originalPrice).toFixed(8))
            : null,
        within_budget: normalizedPrice !== null &&
          budget !== null
            ? normalizedPrice <= budget
            : null
      };
    });

  const comparableOffers = normalizedOffers
    .filter(offer => offer.normalized_price !== null)
    .sort((a, b) => a.normalized_price - b.normalized_price);

  const cheapest = comparableOffers[0] || null;

  const budgetOffers = comparableOffers.filter(
    offer => offer.within_budget === true
  );

  const preferredAirline = String(
    monitor.preferred_airline || ''
  ).trim().toUpperCase();

  const preferredOffers = preferredAirline
    ? comparableOffers.filter(offer =>
        String(offer.airline_code || '').toUpperCase() === preferredAirline ||
        String(offer.airline || '').trim().toUpperCase() === preferredAirline
      )
    : [];

  const cheapestPreferred = preferredOffers[0] || null;

  let fareChange = null;
  let fareChangeAmount = null;
  let fareChangePercent = null;

  if (
    cheapest &&
    previousFare !== null &&
    previousCurrency === targetCurrency
  ) {
    fareChangeAmount = Number(
      (cheapest.normalized_price - previousFare).toFixed(2)
    );

    fareChangePercent = previousFare !== 0
      ? Number(
          ((fareChangeAmount / previousFare) * 100).toFixed(2)
        )
      : null;

    fareChange = fareChangeAmount < 0
      ? 'DECREASE'
      : fareChangeAmount > 0
        ? 'INCREASE'
        : 'NO_CHANGE';
  }

  const events = [];

  if (fareChange === 'DECREASE') events.push('FARE_DECREASE');
  if (fareChange === 'INCREASE') events.push('FARE_INCREASE');
  if (fareChange === 'NO_CHANGE') events.push('NO_FARE_CHANGE');
  if (preferredOffers.length > 0) {
    events.push('PREFERRED_AIRLINE_AVAILABLE');
  }
  if (budgetOffers.length > 0) {
    events.push('BUDGET_OPTION_AVAILABLE');
  }
  if (offers.length === 0) events.push('NO_CURRENT_OFFERS');
  if (comparableOffers.length === 0 && offers.length > 0) {
    events.push('NO_COMPARABLE_OFFERS');
  }

  const meaningfulChange = events.some(event =>
    [
      'FARE_DECREASE',
      'PREFERRED_AIRLINE_AVAILABLE',
      'BUDGET_OPTION_AVAILABLE'
    ].includes(event)
  );

  results.push({
    json: {
      monitor,

      normalized_offers: normalizedOffers,

      monitoring_analysis: {
        ...monitoring,
        current_offer_count: offers.length,
        comparable_offer_count: comparableOffers.length,
        cheapest_current_offer: cheapest,
        preferred_airline: {
          requested: preferredAirline || null,
          available: preferredOffers.length > 0,
          cheapest_offer: cheapestPreferred
        },
        previous_fare: previousFare,
        previous_currency: previousCurrency,
        current_fare: cheapest?.normalized_price ?? null,
        current_currency: targetCurrency,
        fare_change: fareChange,
        fare_change_amount: fareChangeAmount,
        fare_change_percent: fareChangePercent,
        budget,
        budget_currency: targetCurrency,
        budget_offers: budgetOffers,
        budget_option_count: budgetOffers.length,
        events,
        meaningful_change: meaningfulChange,
        currency_normalization:
          comparableOffers.length > 0 ? 'COMPLETED' : 'NO_COMPARABLE_OFFERS',
        exchange_rate_base: baseCode,
        exchange_rate_api_status: exchangeData.result || 'UNKNOWN'
      }
    }
  });
}

return results;

const exchangeData = $input.first().json;

const originalData =
  $('Merge').first().json;

const preferences =
  originalData.preferences || {};

const cheapestOffer =
  originalData.cheapest_offer || null;

const originalFare =
  cheapestOffer?.price != null
    ? Number(cheapestOffer.price)
    : null;

const originalCurrency =
  cheapestOffer?.currency
    ? String(cheapestOffer.currency).toUpperCase()
    : null;

const targetCurrency =
  preferences?.currency
    ? String(preferences.currency).toUpperCase()
    : null;

const userBudget =
  preferences?.budget != null
    ? Number(preferences.budget)
    : null;

const exchangeRate =
  originalCurrency === targetCurrency
    ? 1
    : Number(exchangeData?.rates?.[targetCurrency]);

let convertedFare = null;
let budgetDifference = null;
let withinBudget = null;
let budgetStatus = "UNKNOWN";
let conversionAvailable = false;

if (
  originalFare !== null &&
  Number.isFinite(originalFare) &&
  targetCurrency &&
  exchangeRate !== null &&
  Number.isFinite(exchangeRate)
) {
  conversionAvailable = true;

  convertedFare =
    originalFare * exchangeRate;

  if (
    userBudget !== null &&
    Number.isFinite(userBudget)
  ) {
    budgetDifference =
      userBudget - convertedFare;

    withinBudget =
      convertedFare <= userBudget;

    budgetStatus =
      withinBudget
        ? "WITHIN_BUDGET"
        : "OVER_BUDGET";
  }
}
else if (
  originalCurrency &&
  targetCurrency &&
  originalCurrency === targetCurrency &&
  originalFare !== null
) {
  conversionAvailable = true;
  convertedFare = originalFare;

  if (
    userBudget !== null &&
    Number.isFinite(userBudget)
  ) {
    budgetDifference =
      userBudget - convertedFare;

    withinBudget =
      convertedFare <= userBudget;

    budgetStatus =
      withinBudget
        ? "WITHIN_BUDGET"
        : "OVER_BUDGET";
  }
}
else {
  budgetStatus = "CURRENCY_CONVERSION_UNAVAILABLE";
}

return [
  {
    json: {
      ...originalData,

      currency_conversion: {
        conversion_available: conversionAvailable,

        original_fare: originalFare,
        original_currency: originalCurrency,

        target_currency: targetCurrency,

        exchange_rate: conversionAvailable
          ? exchangeRate
          : null,

        converted_fare:
          convertedFare !== null
            ? Number(convertedFare.toFixed(2))
            : null,

        user_budget: userBudget,

        budget_difference:
          budgetDifference !== null
            ? Number(budgetDifference.toFixed(2))
            : null,

        within_budget: withinBudget,

        budget_status: budgetStatus
      }
    }
  }
];

const decisions = $('Monitoring Decision Agent').all();
const normalizations = $('Monitoring Currency Normalization').all();
const previousStates = $('Load Monitoring State').all();

const count = Math.min(
  decisions.length,
  normalizations.length,
  previousStates.length
);

return Array.from({ length: count }, (_, i) => {
  const decisionData =
    decisions[i].json.output ?? decisions[i].json;

  const normalization = normalizations[i].json;
  const analysis = normalization.output ?? normalization;
  const previousState = previousStates[i].json;

  // Read events from the normalization output.
  const events = Array.isArray(analysis.events)
    ? analysis.events
    : [];

  // Read normalized offers when available.
  const offers = Array.isArray(analysis.normalized_offers)
    ? analysis.normalized_offers
    : [];

  // Avoid reporting NO_CURRENT_OFFERS when valid offers exist.
  const currentEvent = events.length
    ? events.join(',')
    : offers.length > 0
      ? 'OFFERS_AVAILABLE'
      : 'NO_CURRENT_OFFERS';

  // Find the cheapest offer within the budget.
  const budgetOffers = offers.filter(
    offer => offer.within_budget === true
  );

  budgetOffers.sort(
    (a, b) => a.normalized_price - b.normalized_price
  );

  const cheapestOffer = budgetOffers[0];

  // Use the actual normalized fare where available.
  const currentFare =
    cheapestOffer?.normalized_price ??
    analysis.current_fare ??
    analysis.cheapest_current_offer?.normalized_price ??
    '';

  const currentCurrency =
    cheapestOffer?.normalized_currency ??
    analysis.current_currency ??
    analysis.budget_currency ??
    previousState.currency ??
    'INR';

  const preferredAirline =
    previousState.preffered_airline ??
    previousState.preferred_airline ??
    '';

  // Build a signature that represents the monitoring situation.
  const currentSignature = [
    currentEvent,
    currentFare,
    currentCurrency,
    preferredAirline
  ].join('|');

  const previousSignature =
    previousState.last_alert_signature ?? '';

  const signatureChanged =
    currentSignature !== previousSignature;

  // Only alert when the decision agent explicitly recommends ALERT
  // and the monitoring signature has changed.
  const shouldAlert =
    decisionData.decision === 'ALERT' &&
    signatureChanged;

  return {
    json: {
      ...decisionData,
      monitor_id: previousState.monitor_id,
      monitoring_signature: currentSignature,
      previous_monitoring_signature: previousSignature,
      signature_changed: signatureChanged,
      should_alert: shouldAlert
    }
  };
});
